import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

// Opt-in HTTPS for the dev server (`npm run dev:https` sets DANFOLIO_HTTPS=1).
// Live tracking depends on Geolocation, which browsers block outright on
// insecure origins — phones on the LAN open the app over http://<lan-ip>,
// so without HTTPS the rider's device can never publish GPS. The
// self-signed certificate is generated by scripts/gen-dev-cert.sh (system
// openssl, no new dependencies) and is git-ignored under .cert/.
const https =
  process.env.DANFOLIO_HTTPS === '1'
    ? {
        key: readFileSync(fileURLToPath(new URL('.cert/dev-key.pem', import.meta.url))),
        cert: readFileSync(fileURLToPath(new URL('.cert/dev-cert.pem', import.meta.url))),
      }
    : undefined

export default defineConfig({
  plugins: [react()],
  // Bind on all interfaces (0.0.0.0) so phones on the same Wi-Fi can open
  // the app via this Mac's LAN IP — see docs/map-and-live-tracking.md.
  // The IP itself is never hardcoded: Vite prints the Network URLs on start.
  server: { host: true, ...(https ? { https } : {}) },
})
